INSERT OR IGNORE INTO products ("id","sku","name","series","category","price_vnd","price_original","availability","condition","description","images","source_sheet","source_row","source_total","price_overridden","availability_overridden","active","updated_at") VALUES ('sentai-row-141','','Dx Victory Mars','Kyukyu Sentai GoGoFive','Mecha',NULL,NULL,'unknown','','DX Victory Mars (GD-17)
Đây là robot thứ hai, được thiết kế để chiến đấu trong không gian và những môi trường khắc nghiệt mà Victory Robo không thể chịu nhiệt được.
Hợp thể từ: 5 phương tiện Mars Machines (đều là các phi thuyền không gian/tàu thăm dò) [30].
Chất liệu: Cũng thuộc dòng Chogokin, có độ chi tiết cao và màu sắc chủ đạo là đỏ sậm và vàng.
Dạng đặc biệt: Có thể biến thành dạng xe bò khổng lồ gọi là Beetle Mars [30].
Vũ khí: Một cây trượng lớn gọi là Jet Lance, có thể bắn đạn hoặc dùng để đâm xuyên kẻ địch.','["/images/products/image122-d5cb15f1f9af.jpg"]','mecha',141,NULL,0,0,1,'2026-11-04T04:34:18.574Z');
INSERT OR IGNORE INTO products ("id","sku","name","series","category","price_vnd","price_original","availability","condition","description","images","source_sheet","source_row","source_total","price_overridden","availability_overridden","active","updated_at") VALUES ('sentai-row-142','','DX Victory Robo','Kyukyu Sentai GoGoFive','Mecha',NULL,NULL,'unknown','','1. DX Victory Robo (GD-15)
Đây là robot đầu tiên và là biểu tượng của bộ phim, tập trung vào các phương tiện cứu hộ đô thị.
Hợp thể từ: 5 phương tiện 99 Machines (Xe thang, xe vòi rồng, máy bay, xe bọc thép và xe cứu thương) [1, 16].
Chất liệu: Thuộc dòng Chogokin (Siêu hợp kim) với nhiều chi tiết kim loại nặng và bền [1, 19].
Dạng đặc biệt: Có thể biến thành Victory Walker (dạng robot 2 chân nhưng chưa hoàn thiện phần thân trên) để di chuyển nhanh hoặc dập lửa [1, 12].
Vũ khí: Thanh kiếm Brave Sword [19, 25].','["/images/products/image120-221f2b0c53c5.jpg"]','mecha',142,NULL,0,0,1,'2026-11-04T04:34:18.574Z');
